import json, glob, os

SNAP = "2026-02-28"
ORG = "harmonygames-Games"
files = {
 "Combo-Fighters": ["cf_01_13.json","cf_14_25.json","cf_26_37.json"],
 "game-of-dominoes-backend": ["dom_01_14.json","dom_15_28.json","dom_29_42.json","dom_43_56.json","dom_57_68.json","dom_69_79.json"],
}
base="/app/handoff/"
rows=[]
for repo,fs in files.items():
    recs=[]
    for f in fs:
        recs+=json.load(open(base+f))
    recs.sort(key=lambda r:r["number"])
    for r in recs:
        r["repo"]=repo
        rows.append(r)

def d(x):
    return x[:10] if x else None

def commits_cell(r):
    n=r["commits_count"]
    if n==0: return "NONE FOUND"
    if n==1: return f"1 commit; sha {r['commits_first_sha'][:12]}"
    return f"{n} commits; first {r['commits_first_sha'][:12]} → last {r['commits_last_sha'][:12]}"

def reviews_cell(r):
    if r["reviews_count"]==0: return "NONE FOUND"
    people=",".join(r["reviews_users"])
    states=",".join(sorted(set(r["reviews_states"])))
    dates = f"{d(r['reviews_first_date'])}..{d(r['reviews_last_date'])}"
    return f"{r['reviews_count']} review(s); {dates}; people: {people}; states: {states}"

def inline_cell(r):
    if r["inline_count"]==0: return "NONE FOUND"
    people=",".join(r["inline_users"])
    paths=", ".join(r["inline_paths"])
    dates=f"{d(r['inline_first_date'])}..{d(r['inline_last_date'])}"
    return f"{r['inline_count']} inline comment(s); {dates}; people: {people}; files: {paths}"

def general_cell(r):
    if r["general_count"]==0: return "NONE FOUND"
    people=",".join(r["general_users"])
    dates=f"{d(r['general_first_date'])}..{d(r['general_last_date'])}"
    return f"{r['general_count']} comment(s); {dates}; people: {people}"

def lifecycle_cell(r):
    if r["timeline_count"]==0: return "NONE FOUND"
    events=", ".join(r["timeline_events"])
    fd=d(r["timeline_first_date"]); ld=d(r["timeline_last_date"])
    dates = f"{fd}..{ld}" if fd else "undated"
    return f"{r['timeline_count']} event(s); {dates}; events: {events}"

def flags(r):
    fl=[]
    if r["reviews_count"]==0: fl.append("NO_SUBMITTED_REVIEW")
    if r["inline_count"]==0: fl.append("NO_INLINE_REVIEW_DISCUSSION")
    if r["general_count"]==0: fl.append("NO_GENERAL_CONVERSATION")
    if not r["timeline_has_review_requested"]: fl.append("NO_REVIEW_REQUEST_EVENT")
    if r["commits_count"]>1 and not r["reviews_has_approved"]: fl.append("MULTI_COMMIT_WITHOUT_APPROVAL")
    return " | ".join(fl) if fl else "NONE"

register=[]
header=["Repo","PR #","Title","State","Merged","Author","PR URL","Branch (head -> base)","Created (UTC)","Closed/Merged (UTC)","Snapshot cutoff","Commits","Submitted reviews","Inline diff comments","General PR conversation","Lifecycle history","All 5 checks complete","Gap flags"]
register.append(header)
for r in rows:
    url=f"https://github.com/{ORG}/{r['repo']}/pull/{r['number']}"
    closed = r.get("merged_at") or r.get("closed_at") or ""
    row=[
        r["repo"], r["number"], r["title"],
        r["state"], "YES" if r["merged"] else "NO", r["author"], url,
        f"{r['head_ref']} -> {r['base_ref']}",
        r["created_at"], closed, SNAP,
        commits_cell(r), reviews_cell(r), inline_cell(r), general_cell(r), lifecycle_cell(r),
        "COMPLETE (5/5)", flags(r),
    ]
    register.append(row)

# Totals
def flagset(r):
    return flags(r)
FLAGS=["NO_SUBMITTED_REVIEW","NO_INLINE_REVIEW_DISCUSSION","NO_GENERAL_CONVERSATION","NO_REVIEW_REQUEST_EVENT","MULTI_COMMIT_WITHOUT_APPROVAL"]
def count_group(subset):
    fc={f:0 for f in FLAGS}
    fc["NONE"]=0
    for r in subset:
        fstr=flags(r)
        if fstr=="NONE": fc["NONE"]+=1
        else:
            for f in fstr.split(" | "): fc[f]+=1
    return fc

cf=[r for r in rows if r["repo"]=="Combo-Fighters"]
dm=[r for r in rows if r["repo"]=="game-of-dominoes-backend"]
groups={"Combo-Fighters":cf,"game-of-dominoes-backend":dm,"Both combined":rows}

totals_out={}
for name,sub in groups.items():
    fc=count_group(sub)
    totals_out[name]={"pr_count":len(sub), **fc}

json.dump({"register":register,"rows":rows}, open(base+"register.json","w"), indent=1)
json.dump(totals_out, open(base+"totals.json","w"), indent=1)

print("TOTAL ROWS (excl header):", len(register)-1)
for name in groups:
    print(name, totals_out[name])
print("--- open PRs ---", [(r['repo'],r['number']) for r in rows if r['state']=='open'])
# sanity: multi-commit-without-approval list
print("--- MCWA PRs ---")
for r in rows:
    if r["commits_count"]>1 and not r["reviews_has_approved"]:
        print(r["repo"], r["number"], "commits", r["commits_count"], "approved?", r["reviews_has_approved"])

